WITH unpacked AS (SELECT id, plan, currency, discounts, ARRAY_MIN(tier_prices) AS lowest_price, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices, AGGREGATE(tier_prices, 0.0D, (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price FROM price_tiers WHERE currency IN ('THB', 'USD', 'EUR')) SELECT currency, CASE WHEN avg_tier_price >= 26 THEN 'PREMIUM' ELSE 'STANDARD' END AS avg_tier_price_tier, COUNT(CASE WHEN currency = 'EUR' THEN 1 END) AS eur_count, APPROX_PERCENTILE(avg_tier_price, 0.95) AS avg_tier_price_p95, ROUND(AVG(lowest_price), 2) AS avg_lowest_price, COUNT_IF(currency = 'THB') AS thb_events FROM unpacked GROUP BY currency, CASE WHEN avg_tier_price >= 26 THEN 'PREMIUM' ELSE 'STANDARD' END HAVING eur_count < 1 ORDER BY avg_tier_price_tier
